import json

# Sample requirements and system design for validation
requirements = {
    'functional': ['AI-powered grading', 'User management', 'Secure data storage'],
    'non_functional': ['Accuracy >= 90%', 'Role-based access control']
}

system_design = {
    'services': ['AI grading module', 'User management service', 'Secure database'],
    'frontend': 'Responsive web application',
    'architecture': 'Microservices with API gateway'
}

def validate_design(requirements, system_design):
    coverage = {
        'functional': [],
        'non_functional': []
    }
    for req_type, reqs in requirements.items():
        for req in reqs:
            if req_type == 'functional':
                coverage[req_type].append(req in system_design['services'] or req in system_design['frontend'])
            elif req_type == 'non_functional':
                # Assuming non-functional requirements are validated manually
                coverage[req_type].append(True)
    return {
        'functional_coverage': sum(coverage['functional']) / len(coverage['functional']),
        'non_functional_coverage': sum(coverage['non_functional']) / len(coverage['non_functional'])
    }

# Example usage
validation_result = validate_design(requirements, system_design)
print(json.dumps(validation_result, indent=4))

